// Spring Boot: habilitar CORS para el origen de Angular
@CrossOrigin(origins = "http://localhost:4200")

// Angular: servicio consumiendo la API
@Injectable({ providedIn: 'root' })
export class ProductoService {
  private http = inject(HttpClient);
  private api = 'http://localhost:8080/api/productos';

  listar() { return this.http.get<Producto[]>(this.api); }
  crear(p: Producto) { return this.http.post<Producto>(this.api, p); }
}

// En un dispositivo real, "localhost" apunta al propio dispositivo, no a tu PC.
// Usa la IP de tu máquina en la red local durante desarrollo:
private api = 'http://192.168.1.100:8080/api/productos';

// En producción, apunta al dominio real de tu API desplegada (HTTPS obligatorio en iOS):
private api = environment.production
  ? 'https://api.midominio.com/api/productos'
  : 'http://192.168.1.100:8080/api/productos';
